=(int)$navCategory['id']?>#ponuda"><?=e($navCategory['name'])?></a><?php endforeach;else:?><a href="./#ponuda">Izdvojeno za vas</a><?php endif;?><span><?=e(setting('contact_email'))?></span></nav><main id="main-content">
